    border: 3px solid transparent;
    border-radius: 8px;
    background-clip: content-box;
  }
  &:hover::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--c-text-4) 55%, transparent);
    border: 3px solid transparent;
    background-clip: content-box;
  }
}

@utility truncate-1 {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* --------------------------------------------------------- email bodies */
.mail-body {
  color: var(--c-text);
  font-size: 14px;
  line-height: 1.6;
  word-break: break-word;
}
.mail-body p {
  margin: 0 0 1em;
}
.mail-body > *:last-child {
  margin-bottom: 0;
}
.mail-body a {
  color: var(--c-accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 1em;
  padding-left: 26px;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body li {
  margin-bottom: 0.35em;
}
.mail-body strong,
.mail-body b {
  font-weight: 700;
}
.mail-body em,
.mail-body i {
  font-style: italic;
}
.mail-body h1,
.mail-body h2,
.mail-body h3 {
  margin: 0 0 0.6em;
  line-height: 1.3;
  font-weight: 600;
}
.mail-body h1 {
  font-size: 20px;
}
.mail-body h2 {
  font-size: 17px;
}
.mail-body h3 {
  font-size: 15px;
}
.mail-body hr {
  border: 0;
  border-top: 1px solid var(--c-line);
  margin: 1.25em 0;
}
.mail-body blockquote {
  margin: 0 0 1em;
  padding-left: 12px;
  border-left: 2px solid var(--c-line-2);
  color: var(--c-text-2);
}
.mail-body code {
  font-family: 'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  background: var(--c-panel-alt);
  border: 1px solid var(--c-line);
  border-radius: 4px;
  padding: 1px 5px;
}
.mail-body pre {
  font-family: 'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  background: var(--c-panel-alt);
  border: 1px solid var(--c-line);
  border-radius: 8px;
  padding: 12px 14px;
  overflow-x: auto;
  margin: 0 0 1em;
}
.mail-body table {
  border-collapse: collapse;
  margin: 0 0 1em;
  font-size: 13px;
  width: 100%;
}
.mail-body th,
.mail-body td {
  border: 1px solid var(--c-line);
  padding: 7px 10px;
  text-align: left;
}
.mail-body th {
  background: var(--c-panel-alt);
  font-weight: 600;
}
.mail-body .btn-cta {
  display: inline-block;
  background: var(--c-accent);
  color: var(--c-on-accent);
  text-decoration: none;
  padding: 10px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 13px;
}
.mail-body mark,
mark.hl {
  background: #fff3a3;
  color: #1f1f1f;
  border-radius: 2px;
  padding: 0 1px;
}
[data-theme='dark'] .mail-body mark,
[data-theme='dark'] mark.hl {
  background: #6b5a12;
  color: #ffe9a3;
}
.mail-body .quoted {
  color: var(--c-text-3);
  border-left: 2px solid var(--c-line-2);
  padding-left: 12px;
  margin-top: 1em;
}

/* rich-text editor placeholder */
[contenteditable][data-placeholder]:empty::before {
  content: attr(data-placeholder);
  color: var(--c-text-4);
  pointer-events: none;
}

/* ----------------------------------------------------------- animations */
@keyframes gm-fade-in {
  from {
    opacity: 0;
  }
}
@keyframes gm-menu-in {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(-4px);
  }
}
@keyframes gm-sheet-in {
  from {
    transform: translateY(14px);
    opacity: 0;
  }
}
@keyframes gm-snack-in {
  from {
    transform: translateY(90px);
    opacity: 0;
  }
}
@keyframes gm-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes gm-pop {
  50% {
    transform: scale(1.32);
  }
}
@keyframes gm-shimmer {
  100% {
    background-position: 180% 0;
  }
}

.anim-fade {
  animation: gm-fade-in 0.14s ease-out;
}
.anim-menu {
  animation: gm-menu-in 0.13s cubic-bezier(0.2, 0, 0, 1);
}
.anim-sheet {
  animation: gm-sheet-in 0.18s cubic-bezier(0.2, 0, 0, 1);
}
.anim-snack {
  animation: gm-snack-in 0.22s cubic-bezier(0.2, 0, 0, 1);
}
.anim-spin {
  animation: gm-spin 0.9s linear infinite;
}
.anim-pop {
  animation: gm-pop 0.28s ease-out;
}

.skeleton {
  background: linear-gradient(
    90deg,
    var(--c-panel-alt) 25%,
    color-mix(in srgb, var(--c-hover) 70%, var(--c-panel-alt)) 50%,
    var(--c-panel-alt) 75%
  );
  background-size: 220% 100%;
  animation: gm-shimmer 1.15s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* --------------------------------------------------------------- print */
@media print {
  body {
    background: #fff;
  }
  .no-print {
    display: none !important;
  }
  .print-only {
    display: block !important;
  }
  .print-root {
    position: static !important;
    overflow: visible !important;
    height: auto !important;
    display: block !important;
  }
}
.print-only {
  display: none;
}

