462	}
463	
464	export interface View {
465	  kind: ViewKind
466	  labelId?: string
467	  query?: string
468	  category?: Category
469	}
470	
471	const has = (t: Thread, l: string) => t.labels.includes(l)
472	
473	export function viewPredicate(view: View): (t: Thread) => boolean {
474	  switch (view.kind) {
475	    case 'inbox':
476	      return (t) => has(t, SYS.INBOX) && !has(t, SYS.TRASH) && !has(t, SYS.SPAM) && !has(t, SYS.SNOOZED)
477	    case 'starred':
478	      return (t) => has(t, SYS.STARRED) && !has(t, SYS.TRASH) && !has(t, SYS.SPAM)
479	    case 'snoozed':
480	      return (t) => has(t, SYS.SNOOZED) && !has(t, SYS.TRASH)
481	    case 'important':
482	      return (t) => has(t, SYS.IMPORTANT) && !has(t, SYS.TRASH) && !has(t, SYS.SPAM)
483	    case 'sent':
484	      return (t) => has(t, SYS.SENT) && !has(t, SYS.TRASH) && !has(t, SYS.SPAM)
485	    case 'scheduled':
486	      return (t) => has(t, SYS.SCHEDULED) && !has(t, SYS.TRASH)
487	    case 'drafts':
488	      return (t) => has(t, SYS.DRAFT) && !has(t, SYS.TRASH)
489	    case 'spam':
490	      return (t) => has(t, SYS.SPAM)
491	    case 'trash':
492	      return (t) => has(t, SYS.TRASH)
493	    case 'label':
494	      return (t) => !!view.labelId && has(t, view.labelId) && !has(t, SYS.TRASH) && !has(t, SYS.SPAM)
495	    case 'all':
496	    case 'search':
497	      return (t) => !has(t, SYS.TRASH) && !has(t, SYS.SPAM)
498	  }
499	}
500	
501	/** Threads for a mailbox view, already ordered the way the list renders them. */
502	export function selectThreads(state: State, view: View): Thread[] {
503	  const pred = viewPredicate(view)
504	  let out = state.threads.filter(pred)
505	
506	  if (view.kind === 'inbox' && view.category && state.settings.categoryTabs) {
507	    out = out.filter((t) => t.category === view.category)
508	  }
509	
510	  out.sort((a, b) => b.lastActivity - a.lastActivity)
511	
512	  if (state.settings.starredFirst && (view.kind === 'inbox' || view.kind === 'all')) {
513	    const star = (t: Thread) => (has(t, SYS.STARRED) ? 0 : 1)
514	    out.sort((a, b) => star(a) - star(b) || b.lastActivity - a.lastActivity)
515	  }
516	  return out
517	}
518	
519	export interface Counts {
520	  inbox: number
521	  inboxTotal: number
522	  starred: number
523	  snoozed: number
524	  important: number
525	  drafts: number
526	  scheduled: number
527	  spam: number
528	  trash: number
529	  sent: number
530	  all: number
531	  byLabel: Record<string, number>
532	  byCategory: Record<Category, number>
533	}
534	
535	export function selectCounts(state: State): Counts {
536	  const counts: Counts = {
537	    inbox: 0,
538	    inboxTotal: 0,
539	    starred: 0,
540	    snoozed: 0,
541	    important: 0,
542	    drafts: 0,
543	    scheduled: 0,
544	    spam: 0,
545	    trash: 0,
546	    sent: 0,
547	    all: 0,
548	    byLabel: {},
549	    byCategory: { primary: 0, social: 0, promotions: 0, updates: 0, forums: 0 },
550	  }
551	
552	  for (const t of state.threads) {
553	    const trash = has(t, SYS.TRASH)
554	    const spam = has(t, SYS.SPAM)
555	    const unread = isUnread(state, t)
556	
557	    if (trash) counts.trash++
558	    if (spam) counts.spam++
559	    if (trash || spam) continue
560	
561	    counts.all++
562	    if (has(t, SYS.DRAFT)) counts.drafts++
563	    if (has(t, SYS.SCHEDULED)) counts.scheduled++
564	    if (has(t, SYS.SENT)) counts.sent++
565	    if (has(t, SYS.SNOOZED)) counts.snoozed++
566	    if (has(t, SYS.STARRED) && unread) counts.starred++
567	    if (has(t, SYS.IMPORTANT) && unread) counts.important++
568	
569	    if (has(t, SYS.INBOX) && !has(t, SYS.SNOOZED)) {
570	      counts.inboxTotal++
571	      if (unread) {
572	        counts.inbox++
573	        counts.byCategory[t.category]++
574	      }
575	    }
576	
577	    if (unread) {
