    </>
  )
}

/* ---------------------------------------------------------- icon button */

interface IconButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  icon: IconName
  tip?: string
  size?: number
  active?: boolean
  tone?: 'default' | 'star' | 'important' | 'accent'
  padding?: string
}

export function IconButton({
  icon,
  tip,
  size = 20,
  active,
  tone = 'default',
  padding = 'p-2',
  className,
  ...rest
}: IconButtonProps) {
  const toneCls =
    tone === 'star'
      ? active
        ? 'text-star'
        : 'text-ink-4 hover:text-ink-2'
      : tone === 'important'
        ? active
          ? 'text-important'
          : 'text-ink-4 hover:text-ink-2'
        : tone === 'accent'
          ? 'text-accent'
          : active
            ? 'text-ink'
            : 'text-ink-2'

