/** Auto-closing menu wrapper: renders a trigger and its popover together. */
export function MenuButton({
  icon,
  tip,
  children,
  placement = 'bottom-start',
  width,
  size,
  padding,
  className,
  render,
}: {
  icon: IconName
  tip?: string
  children?: (close: () => void) => ReactNode
  placement?: Placement
  width?: number
  size?: number
  padding?: string
  className?: string
  render?: (props: { open: boolean; toggle: () => void; ref: (el: HTMLElement | null) => void }) => ReactNode
}) {
  const [el, setEl] = useState<HTMLElement | null>(null)
  const [open, setOpen] = useState(false)
  const close = useCallback(() => setOpen(false), [])

  return (
    <>
      {render ? (
        render({ open, toggle: () => setOpen((v) => !v), ref: setEl })
      ) : (
        <span ref={setEl} className="contents">
          <IconButton
            icon={icon}
            tip={tip}
            size={size}
            padding={padding}
            className={className}
            active={open}
            aria-haspopup="menu"
            aria-expanded={open}
            onClick={() => setOpen((v) => !v)}
          />
        </span>
      )}
      <Popover anchor={el} open={open} onClose={close} placement={placement} width={width}>
        {children?.(close)}
      </Popover>
    </>
  )
}

