export const cx = (...xs: (string | false | null | undefined)[]) => xs.filter(Boolean).join(' ')

/* -------------------------------------------------------------- tooltip */

interface TipState {
  text: string
  x: number
  y: number
  above: boolean
}

export function Tooltip({
  label,
  children,
  side = 'bottom',
  disabled,
}: {
  label?: string
  children: ReactNode
  side?: 'bottom' | 'top'
  disabled?: boolean
}) {
  const ref = useRef<HTMLSpanElement>(null)
  const [tip, setTip] = useState<TipState | null>(null)
  const timer = useRef<number | undefined>(undefined)

  const show = useCallback(() => {
    if (!label || disabled) return
    window.clearTimeout(timer.current)
    timer.current = window.setTimeout(() => {
      const el = ref.current?.firstElementChild ?? ref.current
      if (!el) return
      const r = el.getBoundingClientRect()
      const above = side === 'top' || r.bottom + 44 > window.innerHeight
      setTip({
        text: label,
        x: Math.min(Math.max(r.left + r.width / 2, 60), window.innerWidth - 60),
        y: above ? r.top - 8 : r.bottom + 8,
        above,
      })
    }, 480)
  }, [label, side, disabled])

  const hide = useCallback(() => {
    window.clearTimeout(timer.current)
    setTip(null)
  }, [])

  useEffect(() => () => window.clearTimeout(timer.current), [])

  return (
    <>
      <span
        ref={ref}
        onPointerEnter={show}
        onPointerLeave={hide}
        onPointerDown={hide}
        className="contents"
      >
        {children}
      </span>
      {tip &&
        createPortal(
          <div
            role="tooltip"
            className="anim-fade pointer-events-none fixed z-[999] max-w-56 rounded bg-tooltip px-2 py-1 text-center text-[11px] leading-4 font-medium text-tooltip-ink shadow-e1"
            style={{
              left: tip.x,
              top: tip.y,
              transform: `translate(-50%, ${tip.above ? '-100%' : '0'})`,
            }}
          >
            {tip.text}
          </div>,
          document.body,
        )}
    </>
  )
}

