              {(close) => <SnoozeMenu ids={sel} close={close} />}
            </MenuButton>
            <MenuButton icon="label" tip="Labels" width={280}>
              {(close) => <LabelMenu ids={sel} close={close} />}
            </MenuButton>
            <MenuButton icon="moveTo" tip="Move to" width={280}>
              {(close) => <MoveMenu ids={sel} close={close} />}
            </MenuButton>
          </span>
          <MenuButton icon="moreVert" tip="More" width={260}>
            {(close) => <MoreMenu ids={sel} close={close} />}
          </MenuButton>
          <span className="ml-2 truncate text-[13px] text-ink-2">
            {sel.length} selected
          </span>
        </div>
      ) : (
        <div className="flex min-w-0 flex-1 items-center gap-0.5 sm:gap-1">
          <IconButton
            icon="refresh"
            tip="Refresh"
            onClick={app.refresh}
            className={app.refreshing ? 'animate-[gm-spin_620ms_linear]' : undefined}
          />
          <MenuButton icon="moreVert" tip="More options" width={240}>
            {(close) => (
              <>
                <MenuItem
                  icon="mailOpen"
                  onClick={() => {
                    close()
                    app.setRead(
                      app.threads.filter((t) => isUnread(state, t)).map((t) => t.id),
                      true,
                    )
                  }}
                >
                  Mark all as read
                </MenuItem>
                <MenuItem
                  icon="settings"
                  onClick={() => {
                    close()
                    app.setDialog({ kind: 'settings' })
                  }}
                >
                  Display settings
                </MenuItem>
                {view === 'trash' && (
                  <MenuItem
                    icon="deleteForever"
                    danger
                    onClick={() => {
                      close()
                      app.deleteForever(app.threads.map((t) => t.id))
                    }}
                  >
                    Empty Trash now
                  </MenuItem>
                )}
                {view === 'spam' && (
                  <MenuItem
                    icon="deleteForever"
                    danger
                    onClick={() => {
                      close()
                      app.deleteForever(app.threads.map((t) => t.id))
                    }}
                  >
                    Delete all spam now
                  </MenuItem>
                )}
              </>
            )}
          </MenuButton>
        </div>
      )}

      <div className="flex flex-none items-center gap-1 pl-1">
        <span
          className={cx(
            'hidden text-[12px] tabular-nums text-ink-2 sm:block',
            !total && 'opacity-0',
          )}
        >
          {start}–{total} of {view === 'inbox' ? counts.inboxTotal || total : total}
        </span>
        <IconButton icon="chevronLeft" tip="Newer" disabled />
        <IconButton icon="chevronRight" tip="Older" disabled />
      </div>
    </div>
  )
}

