function Hl({ text, needles }: { text: string; needles: string[] }) {
  if (!needles.length) return <>{text}</>
  return (
    <>
      {splitHighlight(text, needles).map(([part, hit], i) =>
        hit ? <mark key={i}>{part}</mark> : <span key={i}>{part}</span>,
      )}
    </>
  )
}

