          </Tooltip>
        </span>

        <a
          href={formatHash({ ...app.route, threadId: t.id })}
          onClick={activate}
          className={cx(
            'flex min-w-0 flex-1 items-center gap-2',
            compact && 'flex-col items-stretch gap-0.5 py-1',
          )}
        >
          {compact ? (
            <>
