              </Tooltip>
            )}
            {t.snoozeUntil && (
              <span className="hidden text-[12px] text-accent group-hover:hidden sm:block">
                {whenLabel(t.snoozeUntil)}
              </span>
            )}
            <span
              className={cx(
                'w-[62px] text-right text-[12px] tabular-nums sm:group-hover:hidden',
