import { useEffect, useMemo, useRef, useState } from 'react'
import { useApp } from '../lib/app'
import { CONTACTS, ME, resolveContact } from '../lib/contacts'
import { ATTACHMENT_TINT, fileSize, makeAttachment, whenLabel } from '../lib/format'
import { selectFrequentContacts, useDispatch, useStore } from '../lib/store'
import type { Attachment, ComposeWindow, Contact } from '../lib/types'
import { Icon, type IconName } from './Icon'
import { snoozeOptions } from './Menus'
import { Avatar, Button, cx, IconButton, MenuButton, MenuDivider, MenuItem, Tooltip } from './ui'

const SAMPLE_FILES: [string, number][] = [
  ['Q3-roadmap.pdf', 2_412_000],
  ['orbit-brand-kit.zip', 18_900_000],
  ['revenue-model.xlsx', 486_000],
  ['launch-deck.pptx', 7_240_000],
  ['hero-mockup.png', 1_980_000],
  ['migration-notes.md', 14_800],
]

export function Compose({ win }: { win: ComposeWindow }) {
  const app = useApp()
  const state = useStore()
  const dispatch = useDispatch()

  const [to, setTo] = useState(win.to)
  const [cc, setCc] = useState(win.cc)
  const [bcc, setBcc] = useState(win.bcc)
  const [subject, setSubject] = useState(win.subject)
  const [attachments, setAttachments] = useState<Attachment[]>(win.attachments)
  const [showCc, setShowCc] = useState(win.showCc)
  const [showBcc, setShowBcc] = useState(win.showBcc)
  const [sendAt, setSendAt] = useState<number | undefined>(undefined)
  const [dirty, setDirty] = useState(false)
  const [savedAt, setSavedAt] = useState<number | null>(null)

  const editor = useRef<HTMLDivElement>(null)
  const bodyRef = useRef(win.body)
  const inline = !!win.inline
  const full = win.mode === 'full'

  /* Body lives in a ref so typing never re-renders the app tree. */
  useEffect(() => {
    if (editor.current && editor.current.innerHTML !== bodyRef.current) {
      editor.current.innerHTML = bodyRef.current
    }
  }, [win.mode])

  const draftState = () => ({
    id: win.id,
    to,
    cc,
    bcc,
    subject,
    body: bodyRef.current,
    attachments,
    threadId: win.threadId,
    inReplyTo: win.inReplyTo,
    showCc,
    showBcc,
  })

  const isEmpty = () =>
    !to.length &&
    !cc.length &&
    !bcc.length &&
    !subject.trim() &&
    !attachments.length &&
    !stripHtml(bodyRef.current).trim()

  /* Autosave, exactly like Gmail's silent "Draft saved". */
  const saveTimer = useRef<number | undefined>(undefined)
  const queueSave = () => {
    setDirty(true)
    window.clearTimeout(saveTimer.current)
    saveTimer.current = window.setTimeout(() => {
      if (isEmpty()) return
      dispatch({ t: 'draft:save', draft: draftState(), subject: subject || '(no subject)' })
      setSavedAt(Date.now())
      setDirty(false)
    }, 900)
  }

  // Persist whatever is in flight when the window unmounts.
  const latest = useRef({ isEmpty, draftState, subject })
  latest.current = { isEmpty, draftState, subject }
  useEffect(
    () => () => {
      window.clearTimeout(saveTimer.current)
      if (!latest.current.isEmpty()) {
        dispatch({
          t: 'draft:save',
          draft: latest.current.draftState(),
          subject: latest.current.subject || '(no subject)',
        })
      }
    },
    [dispatch],
  )

  const doSend = (at?: number) => {
    if (!to.length && !cc.length && !bcc.length) {
      app.toast('Add at least one recipient before sending.')
      return
    }
    window.clearTimeout(saveTimer.current)
    app.send({ ...draftState(), sendAt: at }, subject.trim() || '(no subject)', at)
  }

  const discard = () => {
    window.clearTimeout(saveTimer.current)
    dispatch({ t: 'draft:discard', messageId: win.id })
    app.closeCompose(win.id)
    app.toast('Draft discarded.')
  }

  const close = () => {
    window.clearTimeout(saveTimer.current)
    if (isEmpty()) {
      dispatch({ t: 'draft:discard', messageId: win.id })
      app.closeCompose(win.id)
      return
    }
    dispatch({ t: 'draft:save', draft: draftState(), subject: subject || '(no subject)' })
    app.closeCompose(win.id)
    app.toast('Draft saved.')
  }

  const addFile = (name: string, size: number) => {
    setAttachments((prev) => [...prev, makeAttachment(name, size)])
    queueSave()
  }

  /* Ctrl/Cmd+Enter sends from anywhere inside the window. */
  const onKeyDown = (e: React.KeyboardEvent) => {
    if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
      e.preventDefault()
      doSend()
    }
    if (e.key === 'Escape' && !inline) {
      e.stopPropagation()
      close()
    }
  }

  if (win.mode === 'minimized') {
    return (
      <div className="pointer-events-auto flex h-10 w-[280px] items-center gap-1 rounded-t-lg bg-tooltip px-3 text-tooltip-ink shadow-e2">
        <button
          type="button"
          onClick={() => app.updateCompose(win.id, { mode: 'normal' })}
          className="min-w-0 flex-1 truncate text-left text-[13px] font-medium"
        >
          {subject.trim() || 'New message'}
        </button>
        <button
          type="button"
          aria-label="Expand"
          onClick={() => app.updateCompose(win.id, { mode: 'normal' })}
          className="grid size-6 place-items-center rounded hover:bg-white/15"
        >
          <Icon name="expandLess" size={16} />
        </button>
        <button
          type="button"
          aria-label="Save & close"
          onClick={close}
          className="grid size-6 place-items-center rounded hover:bg-white/15"
        >
          <Icon name="close" size={16} />
        </button>
      </div>
    )
  }

  const body = (
    <>
      {!inline && (
        <header className="flex h-10 flex-none items-center gap-1 rounded-t-lg bg-panel-alt px-3">
          <span className="min-w-0 flex-1 truncate text-[13px] font-medium text-ink">
            {win.kind === 'forward'
              ? 'Forward message'
              : win.kind === 'reply' || win.kind === 'replyAll'
                ? 'Reply'
                : subject.trim() || 'New message'}
          </span>
          <IconButton
            icon="minimize"
            tip="Minimise"
            size={16}
            padding="p-1"
            onClick={() => app.updateCompose(win.id, { mode: 'minimized' })}
          />
          <IconButton
            icon={full ? 'fullscreenExit' : 'fullscreen'}
            tip={full ? 'Exit full screen' : 'Full screen'}
            size={16}
            padding="p-1"
            onClick={() => app.updateCompose(win.id, { mode: full ? 'normal' : 'full' })}
          />
          <IconButton icon="close" tip="Save & close" size={16} padding="p-1" onClick={close} />
        </header>
      )}

      <div className="flex min-h-0 flex-1 flex-col">
        <RecipientField
          label="To"
          value={to}
          onChange={(v) => (setTo(v), queueSave())}
          autoFocus={!inline && win.kind === 'new'}
          trailing={
            <div className="flex items-center gap-2 text-[12px] text-ink-3">
              {!showCc && (
                <button type="button" onClick={() => setShowCc(true)} className="hover:text-ink">
                  Cc
                </button>
              )}
              {!showBcc && (
                <button type="button" onClick={() => setShowBcc(true)} className="hover:text-ink">
                  Bcc
                </button>
              )}
            </div>
          }
        />
        {showCc && <RecipientField label="Cc" value={cc} onChange={(v) => (setCc(v), queueSave())} />}
        {showBcc && (
          <RecipientField label="Bcc" value={bcc} onChange={(v) => (setBcc(v), queueSave())} />
        )}

        {!inline && (
          <input
            value={subject}
            onChange={(e) => (setSubject(e.target.value), queueSave())}
            placeholder="Subject"
            aria-label="Subject"
            className="h-10 flex-none border-b border-line-soft px-4 text-[14px] font-medium text-ink outline-none placeholder:font-normal placeholder:text-ink-3"
          />
        )}

        <div
          ref={editor}
          contentEditable
          suppressContentEditableWarning
          role="textbox"
          aria-multiline
          aria-label="Message body"
          onInput={() => {
            bodyRef.current = editor.current?.innerHTML ?? ''
            queueSave()
          }}
          className={cx(
            'mail-body scroll-thin min-h-0 flex-1 overflow-y-auto px-4 py-3 text-[14px] leading-[1.6] text-ink outline-none',
            inline ? 'max-h-[40vh] min-h-[120px]' : 'min-h-[120px]',
          )}
        />

        {!!attachments.length && (
          <div className="flex flex-wrap gap-1.5 border-t border-line-soft px-3 py-2">
            {attachments.map((a) => (
              <span
                key={a.id}
                className="flex max-w-full items-center gap-1.5 rounded border border-line-2 bg-panel-alt py-1 pr-1 pl-2 text-[12px]"
              >
                <span
                  className="grid size-4 flex-none place-items-center rounded-sm text-white"
                  style={{ background: ATTACHMENT_TINT[a.kind] }}
                >
                  <Icon name={a.kind as IconName} size={11} />
                </span>
                <span className="min-w-0 truncate text-ink">{a.name}</span>
                <span className="flex-none text-ink-4">{fileSize(a.size)}</span>
                <button
                  type="button"
                  aria-label={`Remove ${a.name}`}
                  onClick={() => {
                    setAttachments((prev) => prev.filter((x) => x.id !== a.id))
                    queueSave()
                  }}
                  className="grid size-5 flex-none place-items-center rounded-full text-ink-3 hover:bg-hov"
                >
                  <Icon name="close" size={13} />
                </button>
              </span>
            ))}
          </div>
        )}
      </div>

      <footer className="flex h-14 flex-none items-center gap-1 px-2 sm:px-3">
        <div className="flex items-stretch overflow-hidden rounded-full bg-accent text-on-accent">
          <button
            type="button"
            onClick={() => doSend(sendAt)}
            className="h-9 px-5 text-[14px] font-medium transition-[filter] hover:brightness-110"
          >
            {sendAt ? `Send ${whenLabel(sendAt)}` : 'Send'}
          </button>
          <span className="my-2 w-px bg-white/25" />
          <MenuButton
            icon="arrowDropDown"
            tip="Schedule send"
            placement="top-start"
            width={280}
            render={({ toggle, ref }) => (
              <span ref={ref} className="contents">
                <button
                  type="button"
                  aria-label="More send options"
                  onClick={toggle}
                  className="grid h-9 w-8 place-items-center transition-[filter] hover:brightness-110"
                >
                  <Icon name="arrowDropDown" size={20} />
                </button>
              </span>
            )}
          >
            {(closeMenu) => (
              <>
                <MenuItem
                  icon="send"
                  onClick={() => {
                    closeMenu()
                    setSendAt(undefined)
                    doSend()
                  }}
                >
                  Send now
                </MenuItem>
                <MenuDivider />
                {snoozeOptions().map((o) => (
                  <MenuItem
                    key={o.key}
                    icon="scheduleSend"
                    trailing={whenLabel(o.when)}
                    onClick={() => {
                      closeMenu()
                      setSendAt(o.when)
                      doSend(o.when)
                    }}
                  >
                    Schedule for {o.label.toLowerCase()}
                  </MenuItem>
                ))}
              </>
            )}
          </MenuButton>
        </div>

        <MenuButton icon="attach" tip="Attach files" placement="top-start" width={280}>
          {(closeMenu) => (
            <>
              <div className="px-4 pb-1 text-[12px] text-ink-3">
                Pick a sample file to attach
              </div>
              {SAMPLE_FILES.filter((f) => !attachments.some((a) => a.name === f[0])).map(
                ([name, size]) => (
                  <MenuItem
                    key={name}
                    icon="doc"
                    trailing={fileSize(size)}
                    onClick={() => {
                      closeMenu()
                      addFile(name, size)
                    }}
                  >
                    {name}
                  </MenuItem>
                ),
              )}
              {SAMPLE_FILES.every((f) => attachments.some((a) => a.name === f[0])) && (
                <p className="px-4 py-2 text-[13px] text-ink-3">All sample files attached.</p>
              )}
            </>
          )}
        </MenuButton>

        <FormatBar editor={editor} onChange={queueSave} />

        <MenuButton icon="tune" tip="Insert signature" placement="top-start" width={280}>
          {(closeMenu) => (
            <>
              <MenuItem
                icon="person"
                onClick={() => {
                  closeMenu()
                  const sig = `<p><br></p><p>—<br>${state.settings.signature}</p>`
                  bodyRef.current += sig
                  if (editor.current) editor.current.innerHTML = bodyRef.current
                  queueSave()
                }}
              >
                Insert signature
              </MenuItem>
              <MenuItem
                icon="settings"
                onClick={() => {
                  closeMenu()
                  app.setDialog({ kind: 'settings' })
                }}
              >
                Manage signature
              </MenuItem>
            </>
          )}
        </MenuButton>

        <span className="ml-auto flex items-center gap-1">
          <span
            className={cx(
              'mr-1 hidden text-[11px] text-ink-4 transition-opacity sm:block',
              dirty || savedAt ? 'opacity-100' : 'opacity-0',
            )}
          >
            {dirty ? 'Saving…' : savedAt ? 'Draft saved' : ''}
          </span>
          <IconButton icon="trash" tip="Discard draft" size={18} onClick={discard} />
        </span>
      </footer>
    </>
  )

  if (inline) {
    return (
      <div
        onKeyDown={onKeyDown}
        className="flex flex-col overflow-hidden rounded-xl border border-line-2 bg-panel shadow-e1"
      >
        <div className="flex items-center gap-2 border-b border-line-soft px-3 py-2">
          <Avatar name={ME.name} hue={ME.hue} size={28} />
          <span className="text-[13px] text-ink-2">
            {win.kind === 'replyAll' ? 'Reply all' : 'Reply'}
          </span>
          <span className="ml-auto">
            <IconButton
              icon="openInNew"
              tip="Open in new window"
              size={16}
              padding="p-1.5"
              onClick={() => app.updateCompose(win.id, { inline: false })}
            />
          </span>
        </div>
        {body}
      </div>
    )
  }

  return (
    <div
      onKeyDown={onKeyDown}
      className={cx(
        'pointer-events-auto flex flex-col overflow-hidden rounded-t-lg bg-panel shadow-e3',
        full
          ? 'fixed inset-4 z-[210] max-h-none rounded-lg sm:inset-8'
          : 'h-[min(560px,calc(100vh-120px))] w-[min(540px,calc(100vw-24px))]',
      )}
      role="dialog"
      aria-label="Compose message"
    >
      {body}
    </div>
  )
}

/* ------------------------------------------------------------ recipients */

function RecipientField({
  label,
  value,
  onChange,
  autoFocus,
  trailing,
}: {
  label: string
  value: string[]
  onChange: (v: string[]) => void
  autoFocus?: boolean
  trailing?: React.ReactNode
}) {
  const state = useStore()
  const [text, setText] = useState('')
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const [focused, setFocused] = useState(false)
  const input = useRef<HTMLInputElement>(null)

  const frequent = useMemo(() => selectFrequentContacts(state), [state])
  const suggestions = useMemo(() => {
    const q = text.trim().toLowerCase()
    const pool: Contact[] = q
      ? CONTACTS.filter(
          (c) => c.name.toLowerCase().includes(q) || c.email.toLowerCase().includes(q),
        )
      : frequent.slice(0, 8).map(resolveContact)
    return pool.filter((c) => !value.includes(c.email) && c.email !== ME.email).slice(0, 6)
  }, [text, value, frequent])

  const commit = (email: string) => {
    const clean = email.trim().replace(/[,;]$/, '')
    if (!clean) return
    if (!value.includes(clean)) onChange([...value, clean])
    setText('')
    setOpen(false)
    setActive(0)
  }

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (open && suggestions.length) {
      if (e.key === 'ArrowDown') {
        e.preventDefault()
        setActive((i) => (i + 1) % suggestions.length)
        return
      }
      if (e.key === 'ArrowUp') {
        e.preventDefault()
        setActive((i) => (i - 1 + suggestions.length) % suggestions.length)
        return
      }
      if (e.key === 'Enter' || e.key === 'Tab') {
        e.preventDefault()
        commit(suggestions[active].email)
        return
      }
    }
    if (e.key === 'Enter' || e.key === ',' || e.key === ';') {
      e.preventDefault()
      commit(text)
      return
    }
    if (e.key === 'Backspace' && !text && value.length) {
      onChange(value.slice(0, -1))
    }
  }

  return (
    <div className="relative flex min-h-10 flex-none items-start gap-2 border-b border-line-soft px-4 py-1.5">
      <span className="mt-[5px] w-8 flex-none text-[13px] text-ink-3">{label}</span>
      <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1">
        {value.map((email) => {
          const c = resolveContact(email)
          return (
            <Tooltip key={email} label={email}>
              <span className="flex max-w-full items-center gap-1.5 rounded-full bg-hov py-[2px] pr-1 pl-[3px] text-[13px]">
                <Avatar name={c.name} hue={c.hue} size={20} />
                <span className="min-w-0 truncate text-ink">{c.name}</span>
                <button
                  type="button"
                  aria-label={`Remove ${c.name}`}
                  onClick={() => onChange(value.filter((v) => v !== email))}
                  className="grid size-4 flex-none place-items-center rounded-full text-ink-3 hover:bg-hov-strong"
                >
                  <Icon name="close" size={12} />
                </button>
              </span>
            </Tooltip>
          )
        })}
        <input
          ref={input}
          value={text}
          autoFocus={autoFocus}
          aria-label={`${label} recipients`}
          onChange={(e) => {
            setText(e.target.value)
            setOpen(true)
            setActive(0)
          }}
          onKeyDown={onKeyDown}
          onFocus={() => (setFocused(true), setOpen(true))}
          onBlur={() => {
            setFocused(false)
            window.setTimeout(() => setOpen(false), 120)
            if (text.trim()) commit(text)
          }}
          placeholder={value.length ? '' : 'Recipients'}
          className="h-7 min-w-[120px] flex-1 bg-transparent text-[13px] text-ink outline-none placeholder:text-ink-3"
        />
      </div>
      {trailing && (!focused || value.length > 0) && <span className="mt-[5px]">{trailing}</span>}

      {open && suggestions.length > 0 && (
        <ul className="anim-menu absolute top-full left-10 z-[220] mt-0.5 w-[min(360px,calc(100%-40px))] overflow-hidden rounded-lg border border-line bg-raised py-1 shadow-e2">
          {suggestions.map((c, i) => (
            <li key={c.email}>
              <button
                type="button"
                onMouseEnter={() => setActive(i)}
                onMouseDown={(e) => {
                  e.preventDefault()
                  commit(c.email)
                }}
                className={cx(
                  'flex w-full items-center gap-2.5 px-3 py-1.5 text-left',
                  i === active && 'bg-hov',
                )}
              >
                <Avatar name={c.name} hue={c.hue} size={28} />
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-[13px] text-ink">{c.name}</span>
                  <span className="block truncate text-[12px] text-ink-3">{c.email}</span>
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

/* ----------------------------------------------------------- format bar */

const FORMATS: { cmd: string; icon: IconName; tip: string; value?: string }[] = [
  { cmd: 'bold', icon: 'bold', tip: 'Bold (⌘B)' },
  { cmd: 'italic', icon: 'italic', tip: 'Italic (⌘I)' },
  { cmd: 'underline', icon: 'underline', tip: 'Underline (⌘U)' },
  { cmd: 'strikeThrough', icon: 'strike', tip: 'Strikethrough' },
  { cmd: 'insertUnorderedList', icon: 'listBulleted', tip: 'Bulleted list' },
  { cmd: 'insertOrderedList', icon: 'listNumbered', tip: 'Numbered list' },
  { cmd: 'formatBlock', icon: 'quote', tip: 'Block quote', value: 'blockquote' },
  { cmd: 'removeFormat', icon: 'removeFormat', tip: 'Remove formatting' },
]

function FormatBar({
  editor,
  onChange,
}: {
  editor: React.RefObject<HTMLDivElement | null>
  onChange: () => void
}) {
  const [open, setOpen] = useState(false)

  const run = (cmd: string, value?: string) => {
    editor.current?.focus()
    document.execCommand(cmd, false, value)
    onChange()
  }

  return (
    <>
      <IconButton
        icon="formatSize"
        tip="Formatting options"
        active={open}
        onClick={() => setOpen((v) => !v)}
        className="hidden sm:inline-grid"
      />
      {open && (
        <div className="absolute bottom-14 left-2 flex flex-wrap items-center gap-0.5 rounded-lg border border-line bg-raised px-1.5 py-1 shadow-e2">
          {FORMATS.map((f) => (
            <IconButton
              key={f.cmd + (f.value ?? '')}
              icon={f.icon}
              tip={f.tip}
              size={17}
              padding="p-1.5"
              onClick={() => run(f.cmd, f.value)}
            />
          ))}
          <IconButton
            icon="link"
            tip="Insert link"
            size={17}
            padding="p-1.5"
            onClick={() => {
              const url = prompt('Link URL')
              if (url) run('createLink', url)
            }}
          />
        </div>
      )}
    </>
  )
}

/* --------------------------------------------------------------- stack */

export function ComposeStack() {
  const app = useApp()
  const floating = app.compose.filter((c) => !c.inline)
  if (!floating.length) return null

  return (
    <div className="no-print pointer-events-none fixed right-0 bottom-0 z-[200] flex items-end gap-3 px-2 sm:right-4 sm:px-0">
      {floating.map((c) => (
        <Compose key={c.id} win={c} />
      ))}
    </div>
  )
}

function stripHtml(html: string) {
  return html
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
}

/** Compose windows own an unused helper import guard. */
export type { ComposeWindow }

input.content:
import { useEffect, useState } from 'react'
import { useApp } from '../lib/app'
import { ATTACHMENT_TINT, fileSize, fullDate, previewGradient } from '../lib/format'
import { DEFAULT_SETTINGS, useDispatch, useStore } from '../lib/store'
import type { Density, ReadingPane, Settings, ThemePref } from '../lib/types'
import { Icon } from './Icon'
import { SHORTCUTS } from '../lib/shortcuts'
import { Avatar, Button, cx, Dialog, IconButton, Kbd, Radio, Switch } from './ui'
import { ME, resolveContact } from '../lib/contacts'

const LABEL_COLORS = [
  '#1a73e8',
  '#8430ce',
  '#d01884',
  '#d93025',
  '#e8710a',
  '#f9ab00',
  '#188038',
  '#00838f',
  '#5f6368',
  '#3c4043',
  '#c5221f',
  '#b06000',
]

export function Dialogs() {
  const app = useApp()
  const d = app.dialog
  if (!d) return null
  switch (d.kind) {
    case 'settings':
      return <SettingsDialog />
    case 'shortcuts':
      return <ShortcutsDialog />
    case 'newLabel':
      return <LabelDialog seed={d.seed} applyTo={d.applyTo} />
    case 'editLabel':
      return <LabelDialog labelId={d.labelId} />
    case 'attachment':
      return <AttachmentDialog messageId={d.messageId} attachmentId={d.attachmentId} />
    default:
      return null
  }
}

/* ------------------------------------------------------------- settings */

function SettingsDialog() {
  const app = useApp()
  const state = useStore()
  const dispatch = useDispatch()
  const s = state.settings
  const set = (patch: Partial<Settings>) => dispatch({ t: 'settings', patch })
  const close = () => app.setDialog(null)

  return (
    <Dialog
      open
      onClose={close}
      title="Settings"
      width={640}
      footer={
        <>
          <Button
            variant="text"
            onClick={() => {
              set(DEFAULT_SETTINGS)
              app.toast('Settings restored to defaults.')
            }}
          >
            Restore defaults
          </Button>
          <Button variant="filled" onClick={close}>
            Done
          </Button>
        </>
      }
    >
      <Section title="Theme">
        <div className="flex flex-wrap gap-2">
          {(
            [
              ['light', 'Light', 'lightMode'],
              ['dark', 'Dark', 'darkMode'],
              ['system', 'System', 'settings'],
            ] as const
          ).map(([value, title, icon]) => (
            <button
              key={value}
              type="button"
              onClick={() => set({ theme: value as ThemePref })}
              className={cx(
                'flex h-9 items-center gap-2 rounded-full border px-4 text-[13px] transition-colors',
                s.theme === value
                  ? 'border-accent bg-selected-soft font-medium text-accent'
                  : 'border-line-2 text-ink-2 hover:bg-hov',
              )}
            >
              <Icon name={icon} size={17} />
              {title}
            </button>
          ))}
        </div>
      </Section>

      <Section title="Density">
        {(
          [
            ['default', 'Default — comfortable rows with previews'],
            ['comfortable', 'Comfortable — taller rows'],
            ['compact', 'Compact — maximum information density'],
          ] as const
        ).map(([value, title]) => (
          <Radio
            key={value}
            name="density"
            checked={s.density === value}
            onChange={() => set({ density: value as Density })}
          >
            {title}
          </Radio>
        ))}
      </Section>

      <Section title="Reading pane">
        {(
          [
            ['none', 'No split — full-width conversations'],
            ['right', 'Right of list — read while you triage'],
          ] as const
        ).map(([value, title]) => (
          <Radio
            key={value}
            name="pane"
            checked={s.readingPane === value}
            onChange={() => set({ readingPane: value as ReadingPane })}
          >
            {title}
          </Radio>
        ))}
      </Section>

      <Section title="Inbox">
        <Toggle
          label="Category tabs"
          hint="Split the inbox into Primary, Promotions, Social, Updates and Forums."
          value={s.categoryTabs}
          onChange={(v) => set({ categoryTabs: v })}
        />
        <Toggle
          label="Starred first"
          hint="Float starred conversations to the top of the inbox."
          value={s.starredFirst}
          onChange={(v) => set({ starredFirst: v })}
        />
        <Toggle
          label="Preview snippets"
          hint="Show a line of body text next to each subject."
          value={s.snippets}
          onChange={(v) => set({ snippets: v })}
        />
        <Toggle
          label="Sender images"
          hint="Show avatars in the reading view."
          value={s.senderImages}
          onChange={(v) => set({ senderImages: v })}
        />
        <Toggle
          label="Delay marking as read"
          hint="Wait 1.5s before a conversation is marked read."
          value={s.markAsReadDelay}
          onChange={(v) => set({ markAsReadDelay: v })}
        />
        <Toggle
          label="Keyboard shortcuts"
          hint="Enable j/k navigation, e to archive, c to compose and more."
          value={s.shortcuts}
          onChange={(v) => set({ shortcuts: v })}
        />
      </Section>

      <Section title="Signature">
        <textarea
          value={s.signature}
          onChange={(e) => set({ signature: e.target.value })}
          rows={3}
          className="w-full resize-y rounded-lg border border-line-2 bg-transparent px-3 py-2 text-[13px] text-ink outline-none focus:border-accent"
        />
      </Section>

      <Section title="Account">
        <div className="flex items-center gap-3 rounded-xl bg-panel-alt px-3 py-3">
          <Avatar name={ME.name} hue={ME.hue} size={44} />
          <div className="min-w-0 flex-1">
            <p className="truncate text-[14px] text-ink">{ME.name}</p>
            <p className="truncate text-[12px] text-ink-3">{ME.email}</p>
          </div>
          <div className="text-right text-[12px] text-ink-3">
            {ME.storageUsedGb} / {ME.storageTotalGb} GB
          </div>
        </div>
      </Section>
    </Dialog>
  )
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="border-b border-line py-4 last:border-0">
      <h3 className="mb-2 text-[13px] font-medium text-ink">{title}</h3>
      <div className="flex flex-col gap-1">{children}</div>
    </section>
  )
}

function Toggle({
  label,
  hint,
  value,
  onChange,
}: {
  label: string
  hint: string
  value: boolean
  onChange: (v: boolean) => void
}) {
  return (
    <label className="flex cursor-pointer items-start gap-3 py-1.5">
      <span className="mt-[3px]">
        <Switch checked={value} onChange={onChange} label={label} />
      </span>
      <span className="min-w-0 flex-1">
        <span className="block text-[13px] text-ink">{label}</span>
        <span className="block text-[12px] leading-4 text-ink-3">{hint}</span>
      </span>
    </label>
  )
}

/* ------------------------------------------------------------ shortcuts */

function ShortcutsDialog() {
  const app = useApp()
  const state = useStore()
  const dispatch = useDispatch()
  const groups = [...new Set(SHORTCUTS.map((s) => s.group))]

  return (
    <Dialog
      open
      onClose={() => app.setDialog(null)}
      title="Keyboard shortcuts"
      width={720}
      footer={
        <>
          <label className="mr-auto flex items-center gap-2 text-[13px] text-ink-2">
            <Switch
              checked={state.settings.shortcuts}
              onChange={(v) => dispatch({ t: 'settings', patch: { shortcuts: v } })}
              label="Enable keyboard shortcuts"
            />
            Shortcuts {state.settings.shortcuts ? 'on' : 'off'}
          </label>
          <Button variant="filled" onClick={() => app.setDialog(null)}>
            Done
          </Button>
        </>
      }
    >
      <div className="grid gap-x-8 gap-y-1 pb-2 sm:grid-cols-2">
        {groups.map((g) => (
          <div key={g} className="mb-3">
            <h3 className="mb-1.5 text-[12px] font-medium tracking-wide text-ink-3 uppercase">
              {g}
            </h3>
            <ul className="flex flex-col gap-1">
              {SHORTCUTS.filter((s) => s.group === g).map((s) => (
                <li key={s.keys + s.label} className="flex items-baseline gap-3 text-[13px]">
                  <span className="flex flex-none gap-1">
                    {s.keys.split(' ').map((k, i) => (
                      <Kbd key={i}>{k}</Kbd>
                    ))}
                  </span>
                  <span className="min-w-0 flex-1 text-ink-2">{s.label}</span>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </Dialog>
  )
}

/* ---------------------------------------------------------------- label */

function LabelDialog({
  labelId,
  seed,
  applyTo,
}: {
  labelId?: string
  seed?: string
  applyTo?: string[]
}) {
  const app = useApp()
  const state = useStore()
  const dispatch = useDispatch()
  const existing = state.labels.find((l) => l.id === labelId)

  const [name, setName] = useState(existing?.name ?? seed ?? '')
  const [color, setColor] = useState(existing?.color ?? LABEL_COLORS[0])
  const [visible, setVisible] = useState(existing?.visible ?? true)
  const close = () => app.setDialog(null)

  const taken = state.labels.some(
    (l) => l.id !== labelId && l.name.toLowerCase() === name.trim().toLowerCase(),
  )
  const valid = !!name.trim() && !taken

  const submit = () => {
    if (!valid) return
    if (existing) {
      dispatch({ t: 'label:update', id: existing.id, patch: { name: name.trim(), color, visible } })
      app.toast(`Label "${name.trim()}" updated.`)
    } else {
      const id = `lbl_${name.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_')}_${state.labels.length}`
      dispatch({ t: 'label:create', label: { id, name: name.trim(), color, visible } })
      if (applyTo?.length) {
        dispatch({ t: 'patchLabels', ids: applyTo, add: [id] })
        app.toast(`Created "${name.trim()}" and applied it to ${applyTo.length} conversation(s).`)
      } else {
        app.toast(`Label "${name.trim()}" created.`)
      }
    }
    close()
  }

  return (
    <Dialog
      open
      onClose={close}
      title={existing ? 'Edit label' : 'New label'}
      width={440}
      footer={
        <>
          {existing && (
            <Button
              variant="text"
              className="mr-auto !text-danger"
              onClick={() => {
                dispatch({ t: 'label:delete', id: existing.id })
                if (app.route.labelId === existing.id) app.navigate({ kind: 'inbox' })
                app.toast(`Label "${existing.name}" deleted.`)
                close()
              }}
            >
              Delete label
            </Button>
          )}
          <Button variant="text" onClick={close}>
            Cancel
          </Button>
          <Button variant="filled" disabled={!valid} onClick={submit}>
            {existing ? 'Save' : 'Create'}
          </Button>
        </>
      }
    >
      <div className="flex flex-col gap-4 py-2">
        <label className="flex flex-col gap-1.5">
          <span className="text-[12px] text-ink-3">Label name</span>
          <input
            autoFocus
            value={name}
            onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && submit()}
            placeholder="e.g. Contracts"
            className="h-10 rounded-lg border border-line-2 bg-transparent px-3 text-[14px] text-ink outline-none focus:border-accent"
          />
          {taken && <span className="text-[12px] text-danger">A label with that name exists.</span>}
        </label>

        <div className="flex flex-col gap-2">
          <span className="text-[12px] text-ink-3">Colour</span>
          <div className="flex flex-wrap gap-2">
            {LABEL_COLORS.map((c) => (
              <button
                key={c}
                type="button"
                aria-label={`Colour ${c}`}
                onClick={() => setColor(c)}
                className={cx(
                  'grid size-7 place-items-center rounded-full transition-transform',
                  color === c ? 'ring-2 ring-accent ring-offset-2 ring-offset-raised' : 'hover:scale-110',
                )}
                style={{ background: c }}
              >
                {color === c && <Icon name="check" size={15} className="text-white" />}
              </button>
            ))}
          </div>
        </div>

        <label className="flex items-center gap-3">
          <Switch checked={visible} onChange={setVisible} label="Show in sidebar" />
          <span className="text-[13px] text-ink">Show in the sidebar label list</span>
        </label>

        <div className="rounded-lg bg-panel-alt px-3 py-2.5">
          <span className="mb-1.5 block text-[11px] text-ink-3">Preview</span>
          <span className="flex items-center gap-2 text-[13px] text-ink">
            <Icon name="label" size={18} style={{ color }} />
            {name.trim() || 'Label name'}
            <span
              className="ml-1 rounded-[4px] px-1.5 py-[1px] text-[11px] font-medium"
              style={{ background: `${color}22`, color }}
            >
              {name.trim() || 'Label'}
            </span>
          </span>
        </div>
      </div>
    </Dialog>
  )
}

/* ----------------------------------------------------------- attachment */

function AttachmentDialog({
  messageId,
  attachmentId,
}: {
  messageId: string
  attachmentId: string
}) {
  const app = useApp()
  const state = useStore()
  const msg = state.messages[messageId]
  const att = msg?.attachments?.find((a) => a.id === attachmentId)
  const [downloaded, setDownloaded] = useState(false)

  useEffect(() => {
    if (!att) app.setDialog(null)
  }, [att, app])

  if (!msg || !att) return null
  const from = resolveContact(msg.from)

  return (
    <Dialog open onClose={() => app.setDialog(null)} width={860} bare>
      <div className="-mx-6 flex flex-col">
        <div className="flex items-center gap-3 border-b border-line px-5 py-3">
          <span
            className="grid size-9 flex-none place-items-center rounded-lg text-white"
            style={{ background: ATTACHMENT_TINT[att.kind] }}
          >
            <Icon name={att.kind} size={20} />
          </span>
          <div className="min-w-0 flex-1">
            <p className="truncate text-[14px] font-medium text-ink">{att.name}</p>
            <p className="truncate text-[12px] text-ink-3">
              {fileSize(att.size)} · from {from.name} · {fullDate(msg.date)}
            </p>
          </div>
          <Button
            variant="tonal"
            onClick={() => {
              setDownloaded(true)
              app.toast(`“${att.name}” saved to this device (simulated).`)
            }}
          >
            <Icon name="download" size={17} />
            {downloaded ? 'Downloaded' : 'Download'}
          </Button>
          <IconButton icon="close" tip="Close" onClick={() => app.setDialog(null)} />
        </div>

        <div className="grid min-h-[320px] place-items-center bg-panel-alt p-6">
          {att.kind === 'image' ? (
            <div
              className="grid h-[46vh] w-full max-w-[720px] place-items-center rounded-lg shadow-e1"
              style={{ background: att.preview ?? previewGradient(att.name) }}
            >
              <span className="rounded-full bg-black/35 px-3 py-1 text-[12px] text-white backdrop-blur">
                {att.name}
              </span>
            </div>
          ) : (
            <div className="w-full max-w-[640px] rounded-lg bg-panel px-8 py-10 shadow-e1">
              <div className="mb-6 flex items-center gap-2">
                <span
                  className="grid size-7 place-items-center rounded text-white"
                  style={{ background: ATTACHMENT_TINT[att.kind] }}
                >
                  <Icon name={att.kind} size={16} />
                </span>
                <span className="text-[13px] font-medium text-ink-2">{att.name}</span>
              </div>
              <div className="flex flex-col gap-2.5">
                {[92, 78, 96, 61, 88, 45, 90, 70, 34].map((w, i) => (
                  <span
