@import 'tailwindcss';

@custom-variant dark (&:where([data-theme='dark'], [data-theme='dark'] *));

/* ---------------------------------------------------------------- tokens */
:root {
  --c-canvas: #f8fafd;
  --c-panel: #ffffff;
  --c-panel-alt: #f6f8fc;
  --c-raised: #ffffff;
  --c-field: #eaf1fb;
  --c-field-focus: #ffffff;
  --c-hover: #e9eef6;
  --c-hover-strong: #dde3ea;
  --c-selected: #c2dbff;
  --c-selected-soft: #d3e3fd;
  --c-accent: #0b57d0;
  --c-accent-hover: #0842a0;
  --c-on-accent: #ffffff;
  --c-compose: #c2e7ff;
  --c-compose-hover: #b3dcf7;
  --c-on-compose: #001d35;
  --c-text: #1f1f1f;
  --c-text-2: #444746;
  --c-text-3: #5f6368;
  --c-text-4: #80868b;
  --c-text-5: #bdc1c6;
  --c-line: #e3e3e3;
  --c-line-2: #dadce0;
  --c-line-soft: #f1f3f4;
  --c-star: #f4b400;
  --c-danger: #d93025;
  --c-danger-soft: #fce8e6;
  --c-success: #188038;
  --c-warn: #b06000;
  --c-warn-soft: #fef7e0;
  --c-important: #f2a600;
  --c-scrim: rgb(32 33 36 / 0.5);
  --c-tooltip: #3c4043;
  --c-tooltip-text: #ffffff;
  --c-snackbar: #323232;
  --sh-1: 0 1px 2px 0 rgb(60 64 67 / 0.3), 0 1px 3px 1px rgb(60 64 67 / 0.15);
  --sh-2: 0 1px 3px 0 rgb(60 64 67 / 0.3), 0 4px 8px 3px rgb(60 64 67 / 0.15);
  --sh-3: 0 4px 8px 3px rgb(60 64 67 / 0.15), 0 1px 3px rgb(60 64 67 / 0.3);
  color-scheme: light;
}

[data-theme='dark'] {
  --c-canvas: #131314;
  --c-panel: #1e1f20;
  --c-panel-alt: #232427;
  --c-raised: #2a2b2d;
  --c-field: #2f3032;
  --c-field-focus: #37393b;
  --c-hover: #2f3133;
  --c-hover-strong: #3c3e41;
  --c-selected: #1f3760;
  --c-selected-soft: #29405e;
  --c-accent: #a8c7fa;
  --c-accent-hover: #c3ddff;
  --c-on-accent: #062e6f;
  --c-compose: #0842a0;
  --c-compose-hover: #0b57d0;
  --c-on-compose: #ffffff;
  --c-text: #e3e3e3;
  --c-text-2: #c4c7c5;
  --c-text-3: #9aa0a6;
  --c-text-4: #80868b;
  --c-text-5: #5f6368;
  --c-line: #333537;
  --c-line-2: #444746;
  --c-line-soft: #2b2c2e;
  --c-star: #fdd663;
  --c-danger: #f28b82;
  --c-danger-soft: #3f2521;
  --c-success: #81c995;
  --c-warn: #fdd663;
  --c-warn-soft: #3a3020;
  --c-important: #fdd663;
  --c-scrim: rgb(0 0 0 / 0.6);
  --c-tooltip: #e3e3e3;
  --c-tooltip-text: #202124;
  --c-snackbar: #e3e3e3;
  --sh-1: 0 1px 2px 0 rgb(0 0 0 / 0.6), 0 1px 3px 1px rgb(0 0 0 / 0.3);
  --sh-2: 0 1px 3px 0 rgb(0 0 0 / 0.6), 0 4px 8px 3px rgb(0 0 0 / 0.3);
  --sh-3: 0 4px 8px 3px rgb(0 0 0 / 0.4), 0 1px 3px rgb(0 0 0 / 0.6);
  color-scheme: dark;
}

@theme inline {
  --color-canvas: var(--c-canvas);
  --color-panel: var(--c-panel);
  --color-panel-alt: var(--c-panel-alt);
  --color-raised: var(--c-raised);
  --color-field: var(--c-field);
  --color-field-focus: var(--c-field-focus);
  --color-hov: var(--c-hover);
  --color-hov-strong: var(--c-hover-strong);
  --color-selected: var(--c-selected);
  --color-selected-soft: var(--c-selected-soft);
  --color-accent: var(--c-accent);
  --color-accent-hover: var(--c-accent-hover);
  --color-on-accent: var(--c-on-accent);
  --color-compose: var(--c-compose);
  --color-compose-hover: var(--c-compose-hover);
  --color-on-compose: var(--c-on-compose);
  --color-ink: var(--c-text);
  --color-ink-2: var(--c-text-2);
  --color-ink-3: var(--c-text-3);
  --color-ink-4: var(--c-text-4);
  --color-ink-5: var(--c-text-5);
  --color-line: var(--c-line);
  --color-line-2: var(--c-line-2);
  --color-line-soft: var(--c-line-soft);
  --color-star: var(--c-star);
  --color-danger: var(--c-danger);
  --color-danger-soft: var(--c-danger-soft);
  --color-success: var(--c-success);
  --color-warn: var(--c-warn);
  --color-warn-soft: var(--c-warn-soft);
  --color-important: var(--c-important);
  --color-scrim: var(--c-scrim);
  --color-tooltip: var(--c-tooltip);
  --color-tooltip-ink: var(--c-tooltip-text);
  --color-snackbar: var(--c-snackbar);
  --shadow-e1: var(--sh-1);
  --shadow-e2: var(--sh-2);
  --shadow-e3: var(--sh-3);
  --font-sans:
    'Google Sans', 'Google Sans Text', Roboto, -apple-system, BlinkMacSystemFont, 'Segoe UI',
    'Helvetica Neue', Arial, sans-serif;
  --radius-gm: 16px;
}

/* ------------------------------------------------------------- baseline */
@layer base {
  * {
    -webkit-tap-highlight-color: transparent;
  }

  html,
  body,
  #root {
    height: 100%;
  }

  body {
    margin: 0;
    background: var(--c-canvas);
    color: var(--c-text);
    font-family: var(--font-sans);
    font-size: 14px;
    line-height: 1.45;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    overscroll-behavior: none;
  }

  button {
    font: inherit;
    color: inherit;
  }

  input,
  textarea {
    font: inherit;
    color: inherit;
  }

  :focus-visible {
    outline: 2px solid var(--c-accent);
    outline-offset: 1px;
  }

  ::selection {
    background: var(--c-selected-soft);
    color: var(--c-text);
  }
}

/* ------------------------------------------------------------ utilities */
@utility scroll-thin {
  scrollbar-width: thin;
  scrollbar-color: var(--c-line-2) transparent;
  &::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }
  &::-webkit-scrollbar-track {
    background: transparent;
  }
  &::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--c-text-4) 55%, transparent);
    border: 3px solid transparent;
    border-radius: 8px;
    background-clip: content-box;
  }
  &::-webkit-scrollbar-thumb:hover {
    background: color-mix(in srgb, var(--c-text-3) 80%, transparent);
    border: 3px solid transparent;
    background-clip: content-box;
  }
}

/* hide scrollbar until the container is hovered — Gmail behaviour */
@utility scroll-quiet {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
  &:hover {
    scrollbar-color: var(--c-line-2) transparent;
  }
  &::-webkit-scrollbar {
    width: 12px;
  }
  &::-webkit-scrollbar-thumb {
    background: transparent;
    border: 3px solid transparent;
    border-radius: 8px;
    background-clip: content-box;
  }
  &:hover::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--c-text-4) 55%, transparent);
    border: 3px solid transparent;
    background-clip: content-box;
  }
}

@utility truncate-1 {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* --------------------------------------------------------- email bodies */
.mail-body {
  color: var(--c-text);
  font-size: 14px;
  line-height: 1.6;
  word-break: break-word;
}
.mail-body p {
  margin: 0 0 1em;
}
.mail-body > *:last-child {
  margin-bottom: 0;
}
.mail-body a {
  color: var(--c-accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 1em;
  padding-left: 26px;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body li {
  margin-bottom: 0.35em;
}
.mail-body strong,
.mail-body b {
  font-weight: 700;
}
.mail-body em,
.mail-body i {
  font-style: italic;
}
.mail-body h1,
.mail-body h2,
.mail-body h3 {
  margin: 0 0 0.6em;
  line-height: 1.3;
  font-weight: 600;
}
.mail-body h1 {
  font-size: 20px;
}
.mail-body h2 {
  font-size: 17px;
}
.mail-body h3 {
  font-size: 15px;
}
.mail-body hr {
  border: 0;
  border-top: 1px solid var(--c-line);
  margin: 1.25em 0;
}
.mail-body blockquote {
  margin: 0 0 1em;
  padding-left: 12px;
  border-left: 2px solid var(--c-line-2);
  color: var(--c-text-2);
}
.mail-body code {
  font-family: 'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  background: var(--c-panel-alt);
  border: 1px solid var(--c-line);
  border-radius: 4px;
  padding: 1px 5px;
}
.mail-body pre {
  font-family: 'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12.5px;
  background: var(--c-panel-alt);
  border: 1px solid var(--c-line);
  border-radius: 8px;
  padding: 12px 14px;
  overflow-x: auto;
  margin: 0 0 1em;
}
.mail-body table {
  border-collapse: collapse;
  margin: 0 0 1em;
  font-size: 13px;
  width: 100%;
}
.mail-body th,
.mail-body td {
  border: 1px solid var(--c-line);
  padding: 7px 10px;
  text-align: left;
}
.mail-body th {
  background: var(--c-panel-alt);
  font-weight: 600;
}
.mail-body .btn-cta {
  display: inline-block;
  background: var(--c-accent);
  color: var(--c-on-accent);
  text-decoration: none;
  padding: 10px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 13px;
}
.mail-body mark,
mark.hl {
  background: #fff3a3;
  color: #1f1f1f;
  border-radius: 2px;
  padding: 0 1px;
}
[data-theme='dark'] .mail-body mark,
[data-theme='dark'] mark.hl {
  background: #6b5a12;
  color: #ffe9a3;
}
.mail-body .quoted {
  color: var(--c-text-3);
  border-left: 2px solid var(--c-line-2);
  padding-left: 12px;
  margin-top: 1em;
}

/* rich-text editor placeholder */
[contenteditable][data-placeholder]:empty::before {
  content: attr(data-placeholder);
  color: var(--c-text-4);
  pointer-events: none;
}

/* ----------------------------------------------------------- animations */
@keyframes gm-fade-in {
  from {
    opacity: 0;
  }
}
@keyframes gm-menu-in {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(-4px);
  }
}
@keyframes gm-sheet-in {
  from {
    transform: translateY(14px);
    opacity: 0;
  }
}
@keyframes gm-snack-in {
  from {
    transform: translateY(90px);
    opacity: 0;
  }
}
@keyframes gm-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes gm-pop {
  50% {
    transform: scale(1.32);
  }
}
@keyframes gm-shimmer {
  100% {
    background-position: 180% 0;
  }
}

.anim-fade {
  animation: gm-fade-in 0.14s ease-out;
}
.anim-menu {
  animation: gm-menu-in 0.13s cubic-bezier(0.2, 0, 0, 1);
}
.anim-sheet {
  animation: gm-sheet-in 0.18s cubic-bezier(0.2, 0, 0, 1);
}
.anim-snack {
  animation: gm-snack-in 0.22s cubic-bezier(0.2, 0, 0, 1);
}
.anim-spin {
  animation: gm-spin 0.9s linear infinite;
}
.anim-pop {
  animation: gm-pop 0.28s ease-out;
}

.skeleton {
  background: linear-gradient(
    90deg,
    var(--c-panel-alt) 25%,
    color-mix(in srgb, var(--c-hover) 70%, var(--c-panel-alt)) 50%,
    var(--c-panel-alt) 75%
  );
  background-size: 220% 100%;
  animation: gm-shimmer 1.15s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* --------------------------------------------------------------- print */
@media print {
  body {
    background: #fff;
  }
  .no-print {
    display: none !important;
  }
  .print-only {
    display: block !important;
  }
  .print-root {
    position: static !important;
    overflow: visible !important;
    height: auto !important;
    display: block !important;
  }
}
.print-only {
  display: none;
}

