@import 'tailwindcss';

@custom-variant dark (&:where([data-theme='dark'], [data-theme='dark'] *));

/* ---------------------------------------------------------------- tokens */
:root {
  --c-canvas: #f8fafd;
  --c-panel: #ffffff;
  --c-panel-alt: #f6f8fc;
  --c-raised: #ffffff;
  --c-field: #eaf1fb;
