import { chromium } from '/Users/melvynx/Developer/experiments/benchmarks/node_modules/.pnpm/playwright@1.61.1/node_modules/playwright/index.mjs'

const URL = 'http://localhost:9216/'
const DIR = new URL('./shots2/', import.meta.url).pathname
const errors = []

const browser = await chromium.launch()

async function newPage(width, height) {
  const ctx = await browser.newContext({ viewport: { width, height }, deviceScaleFactor: 2 })
  const page = await ctx.newPage()
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()))
  page.on('pageerror', (e) => errors.push(String(e)))
  await page.goto(URL)
  await page.waitForSelector('[role="listitem"]')
  return page
}

/* ------------------------------------------------------------ mobile */
const m = await newPage(390, 844)
const shotM = (n) => m.screenshot({ path: `${DIR}${n}.png`, fullPage: false })

await m.waitForTimeout(400)
await shotM('m1-list')

// tap the avatar to select
await m.locator('[role="listitem"] [role="checkbox"]').nth(1).click()
await m.waitForTimeout(300)
await shotM('m2-selected')
await m.keyboard.press('Escape')

// star from the row
await m.locator('[role="listitem"]').nth(2).locator('button[aria-label*="tarred"]').click()
await m.waitForTimeout(250)
await shotM('m3-starred')

// multi-message thread
await m.locator('[role="listitem"]').nth(3).getByRole('link').click()
await m.waitForTimeout(450)
await shotM('m4-thread')
await m.locator('button[aria-label="Back to list"]').click()

// compose full screen on mobile
await m.getByRole('button', { name: /Compose/i }).first().click()
await m.waitForTimeout(400)
await shotM('m5-compose')

const wide = await m.evaluate(
  () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
)
console.log('mobile overflow px:', wide)
await m.context().close()

/* ----------------------------------------------------------- desktop */
const d = await newPage(1440, 900)
const shotD = (n) => d.screenshot({ path: `${DIR}${n}.png`, fullPage: false })

// a long thread with several messages
const rows = d.locator('[role="listitem"]')
const n = await rows.count()
let opened = false
for (let i = 0; i < n; i++) {
  const label = await rows.nth(i).innerText()
  if (/\b4\b|\b3\b/.test(label)) {
    await rows.nth(i).getByRole('link').click()
    opened = true
    break
  }
}
if (!opened) await rows.first().getByRole('link').click()
await d.waitForTimeout(450)
await shotD('d1-thread-multi')

// expand a collapsed message + show details
const collapsed = d.locator('.mail-body')
console.log('expanded bodies:', await collapsed.count())
await d.locator('button[aria-label="Back to list"]').click()
await d.waitForTimeout(250)

// search results with highlighting
await d.locator('input[aria-label="Search mail"]').click()
await d.keyboard.type('roadmap')
await d.keyboard.press('Enter')
await d.waitForTimeout(400)
await shotD('d2-search')

// search options popover
await d.locator('button[aria-label="Show search options"]').click()
await d.waitForTimeout(300)
await shotD('d3-search-options')
await d.keyboard.press('Escape')

// label creation dialog
await d.goto(URL)
await d.waitForTimeout(300)
await d.locator('button[aria-label="Create new label"]').click()
await d.waitForTimeout(300)
await shotD('d4-label-dialog')
await d.keyboard.press('Escape')

// snooze menu from the row hover actions
await d.locator('[role="listitem"]').first().hover()
await d.waitForTimeout(200)
await shotD('d5-row-hover')

// attachment chip preview
await d.locator('[role="listitem"]').nth(1).getByRole('link').click()
await d.waitForTimeout(400)
const chip = d.locator('button[aria-label^="Preview"]').first()
if (await chip.count()) {
  await chip.click()
  await d.waitForTimeout(400)
  await shotD('d6-attachment')
  await d.keyboard.press('Escape')
} else {
  console.log('no attachment chip found on this thread')
}
await shotD('d7-thread-attach')

// settings, light
await d.locator('button[aria-label="Settings"]').click()
await d.waitForTimeout(250)
await d.getByRole('menuitem', { name: /All settings/i }).click()
await d.waitForTimeout(350)
await shotD('d8-settings-light')

await browser.close()
console.log(errors.length ? `CONSOLE ERRORS:\n${errors.join('\n')}` : 'no console errors')

